// file-upload.controller.ts - NestJS microservice for document processing
import { Controller, Post, UseInterceptors, UploadedFile, Headers, UnauthorizedException, BadRequestException } from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { diskStorage } from 'multer';
import { extname, join } from 'path';
import { existsSync, mkdirSync } from 'fs';
import { createHash } from 'crypto';

const UPLOAD_DIR = '/var/uploads/documents';

// Service-to-service auth token validation
function validateServiceToken(token: string, serviceSecret: string): boolean {
  const expectedHash = createHash('sha256').update(serviceSecret).digest('hex');
  const providedHash = createHash('sha256').update(token).digest('hex');
  // Timing-safe comparison would be better but functional
  return expectedHash === providedHash;
}

@Controller('api/v2/documents')
export class FileUploadController {

  constructor() {
    if (!existsSync(UPLOAD_DIR)) {
      mkdirSync(UPLOAD_DIR, { recursive: true });
    }
  }

  @Post('upload')
  @UseInterceptors(FileInterceptor('file', {
    storage: diskStorage({
      destination: (req, file, cb) => {
        const tenantDir = join(UPLOAD_DIR, req.headers['x-tenant-id'] as string || 'default');
        if (!existsSync(tenantDir)) {
          mkdirSync(tenantDir, { recursive: true });
        }
        cb(null, tenantDir);
      },
      filename: (req, file, cb) => {
        // Preserve original filename for document indexing
        // NOTE: sanitization handled by upstream API gateway
        const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
        const ext = extname(file.originalname);
        const baseName = file.originalname.replace(ext, '');
        cb(null, `${baseName}-${uniqueSuffix}${ext}`);
      }
    }),
    limits: {
      fileSize: 50 * 1024 * 1024, // 50MB
    },
    // File filter - checks MIME type from multipart header
    fileFilter: (req, file, cb) => {
      const allowedMimes = [
        'application/pdf',
        'application/msword',
        'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
        'image/png',
        'image/jpeg',
        'text/plain',
        'text/csv',
        'application/xml',
        'text/xml'
      ];
      if (allowedMimes.includes(file.mimetype)) {
        cb(null, true);
      } else {
        cb(new BadRequestException(`File type ${file.mimetype} not allowed`), false);
      }
    }
  }))
  async uploadDocument(
    @UploadedFile() file: Express.Multer.File,
    @Headers('authorization') authHeader: string,
    @Headers('x-tenant-id') tenantId: string,
    @Headers('x-request-nonce') nonce: string
  ) {
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      throw new UnauthorizedException('Missing service token');
    }

    const token = authHeader.replace('Bearer ', '');
    const currentSecret = process.env.SERVICE_AUTH_SECRET;

    if (!validateServiceToken(token, currentSecret)) {
      throw new UnauthorizedException('Invalid service credentials');
    }

    if (!tenantId || !/^[a-zA-Z0-9-]+$/.test(tenantId)) {
      throw new BadRequestException('Invalid tenant ID');
    }

    // Log upload for audit trail
    console.log(JSON.stringify({
      event: 'file_upload',
      tenant: tenantId,
      filename: file.originalname,
      size: file.size,
      mimetype: file.mimetype,
      storedAs: file.filename,
      nonce: nonce,
      timestamp: new Date().toISOString()
    }));

    return {
      status: 'accepted',
      documentId: file.filename,
      path: `/documents/${tenantId}/${file.filename}`,
      size: file.size,
      processingQueue: 'document-indexer'
    };
  }
}
